// Code generated by gen-nvidia from cublas_api.h. DO NOT EDIT.

package cublas

import (
	"testing"
	"unsafe"
)

func TestGeneratedLayouts(t *testing.T) {
	if got := unsafe.Sizeof(Complex64{}); got != 8 {
		t.Errorf("sizeof(Complex64) = %d, want 8", got)
	}
	if got := unsafe.Alignof(Complex64{}); got != 8 {
		t.Errorf("alignof(Complex64) = %d, want 8", got)
	}
	if got := unsafe.Sizeof(Complex128{}); got != 16 {
		t.Errorf("sizeof(Complex128) = %d, want 16", got)
	}
	t.Log("alignof(Complex128) = 16 in C and cannot be represented by a Go type")
}
